"""The isolated memory-budget check of the job queue with the real pipeline (spec §11,
docs/worker-pipeline.md): fresh MySQL and Kafka containers, the job suites, then the 10
acceptance cases, with the containers, the step trees and the job processes measured
throughout and compared with BUDGETS.

    uv run --group jobs python tests/memory_check.py --preflight     # the machine checks only
    uv run --group jobs python tests/memory_check.py --out data/outputs-memory/<UTC stamp>

Before it starts anything it requires the following, or exits 2:
- a clean worktree, so the record names one commit;
- no running container outside this project, and none of this project's own, which may be
  another session's: it never stops, pauses or removes a container it did not start;
- ports 3307, 9094 and 6380 free, and the snapshot the acceptance cases read.
It then starts MySQL and Kafka, waits for a login and Kafka's metadata, lets the stack idle
for SETTLE_S seconds and requires HOST["idle_available"] available; otherwise it removes the
stack and exits 2.

While pytest runs the job suites and then the acceptance cases, two samplers read:
- every 0.5 s: the host's available memory, and the RSS of every
  `python -m etf_risk.jobs worker|reconciler|submit` process (a submit lasts about a
  second, so its figure is a lower bound);
- every 5 s: the compressor's and swap's size, and each container's cgroup memory.peak,
  memory.stat anon and memory.events. `docker compose restart` resets these counters, so a
  container's figure is the largest over its readings, which stop at most 5 s before each
  restart.
Each step tree's peak summed RSS comes from its launcher's record (sampled every 0.5 s).

The run counts only if memory stayed plentiful. macOS compresses and swaps pages before
memory runs out, and compressed pages leave RSS, so a run on a short host reads low; M2's
informational figures did. A run whose compressor or swap grew by more than HOST's limits
exits 2. A run that counts passes, exit 0, when both pytest runs pass with every acceptance
case run, neither container had an OOM kill, and every figure is within its budget; any miss
exits 1. A container's memory.peak includes page cache and cannot exceed memory.max, so it is
recorded but not budgeted: the containers are judged by anon memory, which they cannot
reclaim without swap, and by OOM kills.

--out receives record.json (settings, tool versions, code state, measurements, verdicts),
samples.jsonl, each pytest run's log and JUnit file, and the launchers' and attempts'
records. pytest's own temporary folders, with the runs' outputs, are removed unless --keep.
The stack is removed at the end (down -v).

AI contribution: written with Claude Code (Opus 5.5).
"""
from __future__ import annotations

import argparse
import json
import os
import platform
import re
import shutil
import signal
import socket
import subprocess
import sys
import tempfile
import threading
import time
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from pathlib import Path

import psutil

REPO = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO / "src"))
from etf_risk import services  # noqa: E402
from etf_risk.provenance import code_state  # noqa: E402

MiB, GiB = 2**20, 2**30
# Proposed on 2026-10-24 from docs/worker-pipeline.md and docs/experiments.md, for the author's
# approval. The containers' limits stay docker/compose.yaml's: 512 MiB and 640 MiB.
BUDGETS = {
    "mysql anon": 410 * MiB,          # 80% of its limit; 264 and 313 MiB after one and two runs (spec §11)
    "kafka anon": 512 * MiB,          # 80% of its limit, with a 256 MiB heap
    "step windows": 512 * MiB,        # 0.12 GiB
    "step spark_pipeline": 3 * GiB,   # native stride 21 with memory to spare: 2.62-2.73 GiB (experiments.md)
    "step verify": 3 * GiB,           # a Spark session too; 0.45-0.58 GiB with memory short
    "process worker": 128 * MiB,      # 63.0 MiB
    "process reconciler": 128 * MiB,  # 51.6 MiB
    "process submit": 128 * MiB,      # not measured before
}
HOST = {
    # one 2.7 GiB step tree (the host lock runs one at a time), 0.3 for the job processes and
    # pytest, 0.5 for both containers growing to their limits, and 0.5 to spare
    "idle_available": 4 * GiB,
    "compressor_growth": 256 * MiB,
    "swap_growth": 256 * MiB,
}
PORTS = (3307, 9094, 6380)
SETTLE_S = 30
SNAPSHOT = REPO / "data" / "processed" / "full-2026-10-12"   # what tests/test_jobs_live_pipeline.py reads
JOB_SUITES = sorted(p.relative_to(REPO).as_posix() for p in (REPO / "tests").glob("test_jobs_*.py"))
ACCEPTANCE = ["tests/test_jobs_live_pipeline.py"]
ROLES = ("worker", "reconciler", "submit")
VM_PROCESS = "com.apple.Virtualization.VirtualMachine"   # Docker Desktop's VM on Apple silicon
CGROUP_SCRIPT = ('cd /sys/fs/cgroup && printf "peak %s\\nlimit %s\\n" "$(cat memory.peak)" "$(cat memory.max)"'
                 ' && grep "^anon " memory.stat && while read k v; do echo "events_$k $v"; done < memory.events')


def now() -> str:
    return datetime.now(timezone.utc).isoformat()


def parse_cgroup(text: str) -> dict:
    """CGROUP_SCRIPT's output as numbers: peak, limit (None for "max"), anon and events_*."""
    values: dict = {}
    for line in text.splitlines():
        key, _, value = line.strip().partition(" ")
        value = value.strip()
        if key and value == "max":
            values[key] = None
        elif key and value.isdigit():
            values[key] = int(value)
    return values


def read_cgroup(service: str) -> dict | None:
    """One reading of the service container's cgroup; None while it cannot be read (paused, restarting)."""
    try:
        out = subprocess.run(["docker", "compose", "-f", str(services.COMPOSE_FILE), "exec", "-T", service,
                              "sh", "-c", CGROUP_SCRIPT], capture_output=True, text=True, timeout=10)
    except subprocess.TimeoutExpired:
        return None
    values = parse_cgroup(out.stdout) if out.returncode == 0 else {}
    return values if isinstance(values.get("peak"), int) and isinstance(values.get("anon"), int) else None


def summarize_container(readings: list[dict | None]) -> dict:
    """A container's readings in time order. A restart starts new counters, seen as memory.peak or
    an event count going down; the limit hits and OOM kills are summed over the container's lives."""
    lives: list[list[dict]] = []
    for r in readings:
        if r is None:
            continue
        last = lives[-1][-1] if lives else None
        if last is None or r["peak"] < last["peak"] or any(
                r.get(k, 0) < last.get(k, 0) for k in ("events_max", "events_oom", "events_oom_kill")):
            lives.append([])
        lives[-1].append(r)
    every = [r for life in lives for r in life]
    return {"readings": len(every), "lives": len(lives),
            "peak_bytes": max((r["peak"] for r in every), default=None),
            "anon_bytes": max((r["anon"] for r in every), default=None),
            "limit_bytes": every[0].get("limit") if every else None,
            "limit_hits": sum(max(r.get("events_max", 0) for r in life) for life in lives),
            "oom_kills": sum(max(r.get("events_oom_kill", 0) for r in life) for life in lives)}


def role(cmdline: list[str] | None) -> str | None:
    """worker, reconciler or submit for `python -m etf_risk.jobs <role> ...`, pytest for `python -m pytest`."""
    if not cmdline or len(cmdline) < 3 or cmdline[1] != "-m":
        return None
    if cmdline[2] == "etf_risk.jobs":
        return cmdline[3] if len(cmdline) > 3 and cmdline[3] in ROLES else None
    return "pytest" if cmdline[2] == "pytest" else None


def compressor_bytes(vm_stat: str) -> int:
    page = int(re.search(r"page size of (\d+) bytes", vm_stat).group(1))
    return int(re.search(r"Pages occupied by compressor:\s+(\d+)", vm_stat).group(1)) * page


def host_memory() -> dict:
    vm_stat = subprocess.run(["vm_stat"], capture_output=True, text=True, timeout=10).stdout
    return {"available_bytes": psutil.virtual_memory().available, "compressor_bytes": compressor_bytes(vm_stat),
            "swap_bytes": psutil.swap_memory().used}


class Sampler:
    """Two sampling threads. Each figure is the largest over the run, available memory the smallest."""

    def __init__(self, samples: Path):
        self.samples, self.stopping = samples, threading.Event()
        self.rss = {name: 0 for name in (*ROLES, "pytest", "vm")}
        self.pids: dict[str, set[int]] = {name: set() for name in self.rss}
        self.available_min: int | None = None
        self.readings: dict[str, list[dict | None]] = {service: [] for service in services.SERVICES}
        self.host: list[dict] = []
        self._roles: dict[tuple[int, float], str | None] = {}
        self._threads = [threading.Thread(target=self._loop, args=(0.5, self._processes), daemon=True),
                         threading.Thread(target=self._loop, args=(5.0, self._containers), daemon=True)]

    def start(self) -> None:
        for thread in self._threads:
            thread.start()

    def stop(self) -> None:
        self.stopping.set()
        for thread in self._threads:
            thread.join()

    def _loop(self, interval: float, sample) -> None:
        while not self.stopping.is_set():
            sample()
            self.stopping.wait(interval)

    def _processes(self) -> None:
        available = psutil.virtual_memory().available
        self.available_min = available if self.available_min is None else min(self.available_min, available)
        for proc in psutil.process_iter(["name", "create_time"]):
            key = (proc.pid, proc.info["create_time"])
            if key not in self._roles:      # a process's command line is read once
                try:
                    self._roles[key] = "vm" if proc.info["name"] == VM_PROCESS else role(proc.cmdline())
                except psutil.Error:
                    self._roles[key] = None
            name = self._roles[key]
            if name:
                try:
                    self.rss[name] = max(self.rss[name], proc.memory_info().rss)
                except psutil.Error:
                    continue
                self.pids[name].add(proc.pid)

    def _containers(self) -> None:
        line = {"at_utc": now(), **host_memory()}
        for service in services.SERVICES:
            line[service] = read_cgroup(service)
            self.readings[service].append(line[service])
        line["rss_bytes"] = dict(self.rss)
        self.host.append(line)
        with self.samples.open("a") as out:
            out.write(json.dumps(line) + "\n")


def launcher_peaks(root: Path) -> dict[str, int]:
    """The largest peak summed RSS per step over every launch under root, failed ones too."""
    peaks: dict[str, int] = {}
    for path in root.glob("**/logs/*.launcher.json"):
        step = path.name.removesuffix(".launcher.json")
        peaks[step] = max(peaks.get(step, 0), json.loads(path.read_text()).get("peak_rss_bytes") or 0)
    return peaks


def job_label(params: dict) -> str:
    return "calendar-year" if params["kind"] == "calendar-year" else f"{params['kind']}, stride {params['stride']}"


def job_peaks(root: Path) -> dict[str, dict[str, int]]:
    """Per kind of job and step, the largest peak over the attempts that wrote attempt.json."""
    peaks: dict[str, dict[str, int]] = {}
    for path in root.glob("**/attempt.json"):
        record = json.loads(path.read_text())
        job = peaks.setdefault(job_label(record["params"]), {})
        for step in record.get("steps", []):
            job[step["name"]] = max(job.get(step["name"], 0), step.get("peak_rss_bytes") or 0)
    return peaks


def keep_records(temp: Path, out: Path) -> None:
    """Copy the launchers' and attempts' records out of pytest's temporary folder."""
    for path in [*temp.glob("**/logs/*.launcher.json"), *temp.glob("**/attempt.json")]:
        target = out / path.relative_to(temp)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, target)


def junit_counts(path: Path) -> dict:
    if not path.exists():
        return {"tests": 0, "failures": 0, "errors": 0, "skipped": 0}
    root = ET.parse(path).getroot()
    suite = root if root.tag == "testsuite" else root.find("testsuite")
    return {key: int(suite.get(key, 0)) for key in ("tests", "failures", "errors", "skipped")}


def run_pytest(name: str, files: list[str], env: dict, out: Path, temp: Path, timeout: float) -> dict:
    """One pytest run with its own temporary folder. On timeout an interrupt lets its fixtures stop
    the processes they started before the process group is killed."""
    junit = out / f"{name}.xml"
    command = [sys.executable, "-m", "pytest", *files, "-q", "-rs", "-p", "no:cacheprovider",
               "--basetemp", str(temp / name), "--junitxml", str(junit)]
    start = time.monotonic()
    with open(out / f"{name}.log", "w") as log:
        process = subprocess.Popen(command, cwd=REPO, env=env, stdout=log, stderr=subprocess.STDOUT,
                                   start_new_session=True)
        try:
            code = process.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            process.send_signal(signal.SIGINT)
            try:
                process.wait(timeout=120)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
            code = None
    return {"exit_code": code, "seconds": round(time.monotonic() - start, 1), **junit_counts(junit)}


def measure(sampler: Sampler, idle: dict, temp: Path, runs: dict) -> dict:
    grew = {key: max((h[f"{key}_bytes"] for h in sampler.host), default=idle[f"{key}_bytes"]) - idle[f"{key}_bytes"]
            for key in ("compressor", "swap")}
    return {"pytest": runs,
            "host": {"idle": idle, "available_min_bytes": sampler.available_min,
                     "compressor_growth_bytes": grew["compressor"], "swap_growth_bytes": grew["swap"],
                     "vm_rss_bytes": sampler.rss["vm"]},
            "containers": {service: summarize_container(sampler.readings[service]) for service in services.SERVICES},
            "steps": launcher_peaks(temp / "acceptance"),
            "jobs": job_peaks(temp / "acceptance"),
            "processes": {name: {"rss_bytes": sampler.rss[name], "processes": len(sampler.pids[name])}
                          for name in (*ROLES, "pytest")}}


def judge(measured: dict, budgets: dict = BUDGETS, host: dict = HOST) -> dict:
    """invalid: why the run does not count; misses: figures above their budgets, and failed runs."""
    invalid: list[str] = []
    misses: list[str] = []

    def within(key: str, value: int) -> None:
        if key not in budgets:
            misses.append(f"{key}: no budget")
        elif value > budgets[key]:
            misses.append(f"{key}: {value / MiB:,.0f} MiB, above its {budgets[key] / MiB:,.0f} MiB")

    for key in ("compressor", "swap"):
        grew, limit = measured["host"][f"{key}_growth_bytes"], host[f"{key}_growth"]
        if grew > limit:
            invalid.append(f"the {key} grew by {grew / MiB:,.0f} MiB, more than {limit / MiB:,.0f} MiB")
    acceptance = measured["pytest"]["acceptance"]
    if acceptance["skipped"] or not acceptance["tests"]:
        invalid.append(f"acceptance cases: {acceptance['tests']} collected, {acceptance['skipped']} skipped")
    for name, run in measured["pytest"].items():
        if run["exit_code"] != 0 or run["failures"] or run["errors"]:
            misses.append(f"pytest {name}: exit {run['exit_code']}, {run['failures']} failed, {run['errors']} errors")
    for service, c in measured["containers"].items():
        if c["anon_bytes"] is None:
            invalid.append(f"{service}: no cgroup reading")
            continue
        if c["oom_kills"]:
            misses.append(f"{service}: {c['oom_kills']} OOM kill(s)")
        within(f"{service} anon", c["anon_bytes"])
    for key in budgets:
        if key.startswith("step ") and key.removeprefix("step ") not in measured["steps"]:
            invalid.append(f"no launch of {key.removeprefix('step ')} was recorded")
    for step, peak in measured["steps"].items():
        within(f"step {step}", peak)
    for name in ROLES:
        if not measured["processes"][name]["processes"]:
            invalid.append(f"no {name} process was sampled")
        else:
            within(f"process {name}", measured["processes"][name]["rss_bytes"])
    return {"counts": not invalid, "passed": not invalid and not misses, "invalid": invalid, "misses": misses}


def first_line(*command: str) -> str | None:
    try:
        out = subprocess.run(command, capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired):
        return None
    lines = (out.stdout or out.stderr).strip().splitlines()
    return lines[0] if lines else None


def machine() -> dict:
    vm_memory = first_line("docker", "info", "--format", "{{.MemTotal}}")
    return {"uv": first_line("uv", "--version"), "java": first_line("java", "-version"),
            "docker": first_line("docker", "version", "--format", "{{.Client.Version}} (server {{.Server.Version}})"),
            "compose": first_line("docker", "compose", "version", "--short"),
            "python": platform.python_version(), "macos": platform.mac_ver()[0], "cpus": psutil.cpu_count(),
            "memory_bytes": psutil.virtual_memory().total,
            "docker_vm_memory_bytes": int(vm_memory) if vm_memory and vm_memory.isdigit() else None}


def compose(*args: str, timeout: float = 300) -> None:
    subprocess.run(["docker", "compose", "-f", str(services.COMPOSE_FILE), *args], check=True,
                   capture_output=True, text=True, timeout=timeout)


def project_containers() -> int:
    """This project's containers, running or not, from any worktree: the Compose name is shared."""
    out = subprocess.run(["docker", "compose", "-f", str(services.COMPOSE_FILE), "ps", "-aq"],
                         capture_output=True, text=True, timeout=60)
    if out.returncode != 0:
        raise RuntimeError(f"docker compose ps failed with exit code {out.returncode}")
    return len(out.stdout.split())


def port_in_use(port: int) -> bool:
    with socket.socket() as s:
        s.settimeout(1)
        return s.connect_ex(("127.0.0.1", port)) == 0


def preflight() -> list[str]:
    """What keeps the check from starting; empty when nothing does."""
    problems = []
    if subprocess.run(["git", "status", "--porcelain"], cwd=REPO, capture_output=True, text=True).stdout.strip():
        problems.append("the worktree has uncommitted changes")
    try:
        if others := services.other_containers():
            problems.append(f"{others} running container(s) outside the {services.PROJECT} project")
        if ours := project_containers():
            problems.append(f"{ours} container(s) of the {services.PROJECT} project exist, maybe another session's")
    except (OSError, RuntimeError, subprocess.TimeoutExpired) as error:
        problems.append(f"docker: {error}")
    if busy := [str(port) for port in PORTS if port_in_use(port)]:
        problems.append(f"port(s) in use: {', '.join(busy)}")
    if not SNAPSHOT.is_dir():
        problems.append(f"no snapshot at {SNAPSHOT.relative_to(REPO)}")
    return problems


def report(record: dict) -> None:
    def mib(value: int | None) -> str:
        return "-" if value is None else f"{value / MiB:,.0f} MiB"

    m, budgets = record["measured"], record["budgets"]
    for service, c in m["containers"].items():
        print(f"{service}: anon {mib(c['anon_bytes'])} (budget {mib(budgets[f'{service} anon'])}); memory.peak "
              f"{mib(c['peak_bytes'])} of {mib(c['limit_bytes'])}; {c['lives']} li{'fe' if c['lives'] == 1 else 'ves'}, "
              f"limit reached {c['limit_hits']} times, {c['oom_kills']} OOM kills")
    for step, peak in sorted(m["steps"].items()):
        print(f"step {step}: {peak / GiB:.2f} GiB (budget {budgets.get(f'step {step}', 0) / GiB:.2f} GiB)")
    for job, steps in sorted(m["jobs"].items()):
        print(f"  {job}: " + ", ".join(f"{step} {peak / GiB:.2f} GiB" for step, peak in steps.items()))
    for name, p in m["processes"].items():
        budget = budgets.get(f"process {name}")
        print(f"{name}: {mib(p['rss_bytes'])} over {p['processes']} process(es)"
              + (f" (budget {mib(budget)})" if budget else ""))
    h = m["host"]
    print(f"host: {h['idle']['available_bytes'] / GiB:.2f} GiB available idle, {h['available_min_bytes'] / GiB:.2f} "
          f"at the lowest; compressor +{mib(h['compressor_growth_bytes'])}, swap +{mib(h['swap_growth_bytes'])}; "
          f"VM process RSS {mib(h['vm_rss_bytes'])}")
    verdict = record["verdict"]
    for reason in verdict["invalid"]:
        print(f"does not count: {reason}")
    for miss in verdict["misses"]:
        print(f"miss: {miss}")
    print("passed" if verdict["passed"] else "counts, failed" if verdict["counts"] else "does not count")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--out", type=Path, help="a new folder for record.json, the samples and the pytest logs")
    parser.add_argument("--preflight", action="store_true", help="only check that the run can start")
    parser.add_argument("--keep", action="store_true", help="keep pytest's temporary folders with the runs' outputs")
    args = parser.parse_args(argv)
    if not args.preflight and args.out is None:
        parser.error("--out is required, unless --preflight")
    problems = preflight()
    print(f"available now: {psutil.virtual_memory().available / GiB:.2f} GiB; with the stack up and idle "
          f"the run needs {HOST['idle_available'] / GiB:.1f} GiB")
    for problem in problems:
        print(f"not ready: {problem}")
    if args.preflight or problems:
        return 2 if problems else 0
    args.out.mkdir(parents=True)   # a new folder, so no record is overwritten
    temp = Path(tempfile.mkdtemp(prefix="etf-risk-memory-"))
    record: dict = {"format": 1, "started_at_utc": now(), "code": code_state(), "machine": machine(),
                    "budgets": BUDGETS, "host_limits": HOST, "settle_s": SETTLE_S, "pytest_temp": str(temp)}
    try:
        subprocess.Popen(["caffeinate", "-i", "-w", str(os.getpid())])   # no idle sleep while this runs
    except OSError:
        pass
    env = {**os.environ, "ETF_RISK_MYSQL_URL": services.DEFAULT_MYSQL_URL,
           "ETF_RISK_KAFKA_BOOTSTRAP": services.DEFAULT_KAFKA_BOOTSTRAP}
    started = False
    try:
        compose("up", "-d", "--wait", *services.SERVICES)
        started = True
        subprocess.run([sys.executable, "-m", "etf_risk.services", "ready", *services.SERVICES], cwd=REPO, env=env,
                       check=True, timeout=300)
        time.sleep(SETTLE_S)
        record["idle"] = idle = host_memory()
        print(f"idle with the stack up: {idle['available_bytes'] / GiB:.2f} GiB available")
        if idle["available_bytes"] < HOST["idle_available"]:
            record["verdict"] = {"counts": False, "passed": False, "misses": [],
                                 "invalid": [f"{idle['available_bytes'] / GiB:.2f} GiB available with the stack idle"]}
            print(f"not ready: below {HOST['idle_available'] / GiB:.1f} GiB")
            return 2
        sampler, runs = Sampler(args.out / "samples.jsonl"), {}
        sampler.start()
        try:
            runs["suites"] = run_pytest("suites", JOB_SUITES, env, args.out, temp, 1800)
            print(f"job suites: {runs['suites']}")
            runs["acceptance"] = run_pytest("acceptance", ACCEPTANCE, {**env, "ETF_RISK_LIVE_PIPELINE": "1"},
                                            args.out, temp, 3600)
            print(f"acceptance cases: {runs['acceptance']}")
        finally:
            sampler.stop()
        record["measured"] = measure(sampler, idle, temp, runs)
        record["verdict"] = judge(record["measured"])
    finally:
        if started:
            compose("down", "-v")
        record["ended_at_utc"] = now()
        record["project_containers_after"] = project_containers()
        keep_records(temp, args.out / "records")
        if not args.keep:
            shutil.rmtree(temp, ignore_errors=True)
        (args.out / "record.json").write_text(json.dumps(record, indent=2) + "\n")
    report(record)
    return 0 if record["verdict"]["passed"] else 1 if record["verdict"]["counts"] else 2


if __name__ == "__main__":
    sys.exit(main())

toolu_01Xe25syP7afDbWohbkewNXs.content:
"""The isolated memory-budget check of the job queue with the real pipeline (spec §11,
docs/worker-pipeline.md): fresh MySQL and Kafka containers, the job suites, then the 10
acceptance cases, with the containers, the step trees and the job processes measured
throughout and compared with BUDGETS.

    uv run --group jobs python tests/memory_check.py --preflight     # the machine checks only
    uv run --group jobs python tests/memory_check.py --out data/outputs-memory/<UTC stamp>

Before it starts anything it requires the following, or exits 2:
- a clean worktree, so the record names one commit;
- no running container outside this project, and none of this project's own, which may be
  another session's: it never stops, pauses or removes a container it did not start;
- ports 3307, 9094 and 6380 free, and the snapshot the acceptance cases read.
It then starts MySQL and Kafka, waits for a login and Kafka's metadata, lets the stack idle
for SETTLE_S seconds and requires HOST["idle_available"] available; otherwise it removes the
stack and exits 2.

While pytest runs the job suites and then the acceptance cases, two samplers read:
- every 0.5 s: the host's available memory, and the RSS of every
  `python -m etf_risk.jobs worker|reconciler|submit` process (a submit lasts about a
  second, so its figure is a lower bound);
- every 5 s: the compressor's and swap's size, and each container's cgroup memory.peak,
  memory.stat anon and memory.events. `docker compose restart` resets these counters, so a
  container's figure is the largest over its readings, which stop at most 5 s before each
  restart.
Each step tree's peak summed RSS comes from its launcher's record (sampled every 0.5 s).

The run counts only if memory stayed plentiful. macOS compresses and swaps pages before
memory runs out, and compressed pages leave RSS, so a run on a short host reads low; M2's
informational figures did. A run whose compressor or swap grew by more than HOST's limits
exits 2. A run that counts passes, exit 0, when both pytest runs pass with every acceptance
case run, neither container had an OOM kill, and every figure is within its budget; any miss
exits 1. A container's memory.peak includes page cache and cannot exceed memory.max, so it is
recorded but not budgeted: the containers are judged by anon memory, which they cannot
reclaim without swap, and by OOM kills.

--out receives record.json (settings, tool versions, code state, measurements, verdicts),
samples.jsonl, each pytest run's log and JUnit file, and the launchers' and attempts'
records. pytest's own temporary folders, with the runs' outputs, are removed unless --keep.
The stack is removed at the end (down -v).

AI contribution: written with Claude Code (Opus 5.5).
"""
from __future__ import annotations

import argparse
import json
import os
import platform
import re
import shutil
import signal
import socket
import subprocess
import sys
import tempfile
import threading
import time
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from pathlib import Path

import psutil

REPO = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO / "src"))
from etf_risk import services  # noqa: E402
from etf_risk.provenance import code_state  # noqa: E402

MiB, GiB = 2**20, 2**30
# Proposed on 2026-10-24 from docs/worker-pipeline.md and docs/experiments.md, for the author's
# approval. The containers' limits stay docker/compose.yaml's: 512 MiB and 640 MiB.
BUDGETS = {
    "mysql anon": 410 * MiB,          # 80% of its limit; 264 and 313 MiB after one and two runs (spec §11)
    "kafka anon": 512 * MiB,          # 80% of its limit, with a 256 MiB heap
    "step windows": 512 * MiB,        # 0.12 GiB
    "step spark_pipeline": 3 * GiB,   # native stride 21 with memory to spare: 2.62-2.73 GiB (experiments.md)
    "step verify": 3 * GiB,           # a Spark session too; 0.45-0.58 GiB with memory short
    "process worker": 128 * MiB,      # 63.0 MiB
    "process reconciler": 128 * MiB,  # 51.6 MiB
    "process submit": 128 * MiB,      # not measured before
}
HOST = {
    # one 2.7 GiB step tree (the host lock runs one at a time), 0.3 for the job processes and
    # pytest, 0.5 for both containers growing to their limits, and 0.5 to spare
    "idle_available": 4 * GiB,
    "compressor_growth": 256 * MiB,
    "swap_growth": 256 * MiB,
}
PORTS = (3307, 9094, 6380)
SETTLE_S = 30
SNAPSHOT = REPO / "data" / "processed" / "full-2026-10-12"   # what tests/test_jobs_live_pipeline.py reads
JOB_SUITES = sorted(p.relative_to(REPO).as_posix() for p in (REPO / "tests").glob("test_jobs_*.py"))
ACCEPTANCE = ["tests/test_jobs_live_pipeline.py"]
ROLES = ("worker", "reconciler", "submit")
VM_PROCESS = "com.apple.Virtualization.VirtualMachine"   # Docker Desktop's VM on Apple silicon
CGROUP_SCRIPT = ('cd /sys/fs/cgroup && printf "peak %s\\nlimit %s\\n" "$(cat memory.peak)" "$(cat memory.max)"'
                 ' && grep "^anon " memory.stat && while read k v; do echo "events_$k $v"; done < memory.events')


def now() -> str:
    return datetime.now(timezone.utc).isoformat()


def parse_cgroup(text: str) -> dict:
    """CGROUP_SCRIPT's output as numbers: peak, limit (None for "max"), anon and events_*."""
    values: dict = {}
    for line in text.splitlines():
        key, _, value = line.strip().partition(" ")
        value = value.strip()
        if key and value == "max":
            values[key] = None
        elif key and value.isdigit():
            values[key] = int(value)
    return values


def read_cgroup(service: str) -> dict | None:
    """One reading of the service container's cgroup; None while it cannot be read (paused, restarting)."""
    try:
        out = subprocess.run(["docker", "compose", "-f", str(services.COMPOSE_FILE), "exec", "-T", service,
                              "sh", "-c", CGROUP_SCRIPT], capture_output=True, text=True, timeout=10)
    except subprocess.TimeoutExpired:
        return None
    values = parse_cgroup(out.stdout) if out.returncode == 0 else {}
    return values if isinstance(values.get("peak"), int) and isinstance(values.get("anon"), int) else None


def summarize_container(readings: list[dict | None]) -> dict:
    """A container's readings in time order. A restart starts new counters, seen as memory.peak or
    an event count going down; the limit hits and OOM kills are summed over the container's lives."""
    lives: list[list[dict]] = []
    for r in readings:
        if r is None:
            continue
        last = lives[-1][-1] if lives else None
        if last is None or r["peak"] < last["peak"] or any(
                r.get(k, 0) < last.get(k, 0) for k in ("events_max", "events_oom", "events_oom_kill")):
            lives.append([])
        lives[-1].append(r)
    every = [r for life in lives for r in life]
    return {"readings": len(every), "lives": len(lives),
            "peak_bytes": max((r["peak"] for r in every), default=None),
            "anon_bytes": max((r["anon"] for r in every), default=None),
            "limit_bytes": every[0].get("limit") if every else None,
            "limit_hits": sum(max(r.get("events_max", 0) for r in life) for life in lives),
            "oom_kills": sum(max(r.get("events_oom_kill", 0) for r in life) for life in lives)}


def role(cmdline: list[str] | None) -> str | None:
    """worker, reconciler or submit for `python -m etf_risk.jobs <role> ...`, pytest for `python -m pytest`."""
    if not cmdline or len(cmdline) < 3 or cmdline[1] != "-m":
        return None
    if cmdline[2] == "etf_risk.jobs":
        return cmdline[3] if len(cmdline) > 3 and cmdline[3] in ROLES else None
    return "pytest" if cmdline[2] == "pytest" else None


def compressor_bytes(vm_stat: str) -> int:
    page = int(re.search(r"page size of (\d+) bytes", vm_stat).group(1))
    return int(re.search(r"Pages occupied by compressor:\s+(\d+)", vm_stat).group(1)) * page


def host_memory() -> dict:
    vm_stat = subprocess.run(["vm_stat"], capture_output=True, text=True, timeout=10).stdout
    return {"available_bytes": psutil.virtual_memory().available, "compressor_bytes": compressor_bytes(vm_stat),
            "swap_bytes": psutil.swap_memory().used}


class Sampler:
    """Two sampling threads. Each figure is the largest over the run, available memory the smallest."""

    def __init__(self, samples: Path):
        self.samples, self.stopping = samples, threading.Event()
        self.rss = {name: 0 for name in (*ROLES, "pytest", "vm")}
        self.pids: dict[str, set[int]] = {name: set() for name in self.rss}
        self.available_min: int | None = None
        self.readings: dict[str, list[dict | None]] = {service: [] for service in services.SERVICES}
        self.host: list[dict] = []
        self._roles: dict[tuple[int, float], str | None] = {}
        self._threads = [threading.Thread(target=self._loop, args=(0.5, self._processes), daemon=True),
                         threading.Thread(target=self._loop, args=(5.0, self._containers), daemon=True)]

    def start(self) -> None:
        for thread in self._threads:
            thread.start()

    def stop(self) -> None:
        self.stopping.set()
        for thread in self._threads:
            thread.join()

    def _loop(self, interval: float, sample) -> None:
        while not self.stopping.is_set():
            sample()
            self.stopping.wait(interval)

    def _processes(self) -> None:
        available = psutil.virtual_memory().available
        self.available_min = available if self.available_min is None else min(self.available_min, available)
        for proc in psutil.process_iter(["name", "create_time"]):
            key = (proc.pid, proc.info["create_time"])
            if key not in self._roles:      # a process's command line is read once
                try:
                    self._roles[key] = "vm" if proc.info["name"] == VM_PROCESS else role(proc.cmdline())
                except psutil.Error:
                    self._roles[key] = None
            name = self._roles[key]
            if name:
                try:
                    self.rss[name] = max(self.rss[name], proc.memory_info().rss)
                except psutil.Error:
                    continue
                self.pids[name].add(proc.pid)

    def _containers(self) -> None:
        line = {"at_utc": now(), **host_memory()}
        for service in services.SERVICES:
            line[service] = read_cgroup(service)
            self.readings[service].append(line[service])
        line["rss_bytes"] = dict(self.rss)
        self.host.append(line)
        with self.samples.open("a") as out:
            out.write(json.dumps(line) + "\n")


def launcher_peaks(root: Path) -> dict[str, int]:
    """The largest peak summed RSS per step over every launch under root, failed ones too."""
    peaks: dict[str, int] = {}
    for path in root.glob("**/logs/*.launcher.json"):
        step = path.name.removesuffix(".launcher.json")
        peaks[step] = max(peaks.get(step, 0), json.loads(path.read_text()).get("peak_rss_bytes") or 0)
    return peaks


def job_label(params: dict) -> str:
    return "calendar-year" if params["kind"] == "calendar-year" else f"{params['kind']}, stride {params['stride']}"


def job_peaks(root: Path) -> dict[str, dict[str, int]]:
    """Per kind of job and step, the largest peak over the attempts that wrote attempt.json."""
    peaks: dict[str, dict[str, int]] = {}
    for path in root.glob("**/attempt.json"):
        record = json.loads(path.read_text())
        job = peaks.setdefault(job_label(record["params"]), {})
        for step in record.get("steps", []):
            job[step["name"]] = max(job.get(step["name"], 0), step.get("peak_rss_bytes") or 0)
    return peaks


def keep_records(temp: Path, out: Path) -> None:
    """Copy the launchers' and attempts' records out of pytest's temporary folder."""
    for path in [*temp.glob("**/logs/*.launcher.json"), *temp.glob("**/attempt.json")]:
        target = out / path.relative_to(temp)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, target)


def junit_counts(path: Path) -> dict:
    if not path.exists():
        return {"tests": 0, "failures": 0, "errors": 0, "skipped": 0}
    root = ET.parse(path).getroot()
    suite = root if root.tag == "testsuite" else root.find("testsuite")
    return {key: int(suite.get(key, 0)) for key in ("tests", "failures", "errors", "skipped")}


def run_pytest(name: str, files: list[str], env: dict, out: Path, temp: Path, timeout: float) -> dict:
    """One pytest run with its own temporary folder. On timeout an interrupt lets its fixtures stop
    the processes they started before the process group is killed."""
    junit = out / f"{name}.xml"
    command = [sys.executable, "-m", "pytest", *files, "-q", "-rs", "-p", "no:cacheprovider",
               "--basetemp", str(temp / name), "--junitxml", str(junit)]
    start = time.monotonic()
    with open(out / f"{name}.log", "w") as log:
        process = subprocess.Popen(command, cwd=REPO, env=env, stdout=log, stderr=subprocess.STDOUT,
                                   start_new_session=True)
        try:
            code = process.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            process.send_signal(signal.SIGINT)
            try:
                process.wait(timeout=120)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
            code = None
    return {"exit_code": code, "seconds": round(time.monotonic() - start, 1), **junit_counts(junit)}


def measure(sampler: Sampler, idle: dict, temp: Path, runs: dict) -> dict:
    grew = {key: max((h[f"{key}_bytes"] for h in sampler.host), default=idle[f"{key}_bytes"]) - idle[f"{key}_bytes"]
            for key in ("compressor", "swap")}
    return {"pytest": runs,
            "host": {"idle": idle, "available_min_bytes": sampler.available_min,
                     "compressor_growth_bytes": grew["compressor"], "swap_growth_bytes": grew["swap"],
                     "vm_rss_bytes": sampler.rss["vm"]},
            "containers": {service: summarize_container(sampler.readings[service]) for service in services.SERVICES},
            "steps": launcher_peaks(temp / "acceptance"),
            "jobs": job_peaks(temp / "acceptance"),
            "processes": {name: {"rss_bytes": sampler.rss[name], "processes": len(sampler.pids[name])}
                          for name in (*ROLES, "pytest")}}


def judge(measured: dict, budgets: dict = BUDGETS, host: dict = HOST) -> dict:
    """invalid: why the run does not count; misses: figures above their budgets, and failed runs."""
    invalid: list[str] = []
    misses: list[str] = []

    def within(key: str, value: int) -> None:
        if key not in budgets:
            misses.append(f"{key}: no budget")
        elif value > budgets[key]:
            misses.append(f"{key}: {value / MiB:,.0f} MiB, above its {budgets[key] / MiB:,.0f} MiB")

    for key in ("compressor", "swap"):
        grew, limit = measured["host"][f"{key}_growth_bytes"], host[f"{key}_growth"]
        if grew > limit:
            invalid.append(f"the {key} grew by {grew / MiB:,.0f} MiB, more than {limit / MiB:,.0f} MiB")
    acceptance = measured["pytest"]["acceptance"]
    if acceptance["skipped"] or not acceptance["tests"]:
        invalid.append(f"acceptance cases: {acceptance['tests']} collected, {acceptance['skipped']} skipped")
    for name, run in measured["pytest"].items():
        if run["exit_code"] != 0 or run["failures"] or run["errors"]:
            misses.append(f"pytest {name}: exit {run['exit_code']}, {run['failures']} failed, {run['errors']} errors")
    for service, c in measured["containers"].items():
        if c["anon_bytes"] is None:
            invalid.append(f"{service}: no cgroup reading")
            continue
        if c["oom_kills"]:
            misses.append(f"{service}: {c['oom_kills']} OOM kill(s)")
        within(f"{service} anon", c["anon_bytes"])
    for key in budgets:
        if key.startswith("step ") and key.removeprefix("step ") not in measured["steps"]:
            invalid.append(f"no launch of {key.removeprefix('step ')} was recorded")
    for step, peak in measured["steps"].items():
        within(f"step {step}", peak)
    for name in ROLES:
        if not measured["processes"][name]["processes"]:
            invalid.append(f"no {name} process was sampled")
        else:
            within(f"process {name}", measured["processes"][name]["rss_bytes"])
    return {"counts": not invalid, "passed": not invalid and not misses, "invalid": invalid, "misses": misses}


def first_line(*command: str) -> str | None:
    try:
        out = subprocess.run(command, capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired):
        return None
    lines = (out.stdout or out.stderr).strip().splitlines()
    return lines[0] if lines else None


def machine() -> dict:
    vm_memory = first_line("docker", "info", "--format", "{{.MemTotal}}")
    return {"uv": first_line("uv", "--version"), "java": first_line("java", "-version"),
            "docker": first_line("docker", "version", "--format", "{{.Client.Version}} (server {{.Server.Version}})"),
            "compose": first_line("docker", "compose", "version", "--short"),
            "python": platform.python_version(), "macos": platform.mac_ver()[0], "cpus": psutil.cpu_count(),
            "memory_bytes": psutil.virtual_memory().total,
            "docker_vm_memory_bytes": int(vm_memory) if vm_memory and vm_memory.isdigit() else None}


def compose(*args: str, timeout: float = 300) -> None:
    subprocess.run(["docker", "compose", "-f", str(services.COMPOSE_FILE), *args], check=True,
                   capture_output=True, text=True, timeout=timeout)


def project_containers() -> int:
    """This project's containers, running or not, from any worktree: the Compose name is shared."""
    out = subprocess.run(["docker", "compose", "-f", str(services.COMPOSE_FILE), "ps", "-aq"],
                         capture_output=True, text=True, timeout=60)
    if out.returncode != 0:
        raise RuntimeError(f"docker compose ps failed with exit code {out.returncode}")
    return len(out.stdout.split())


def port_in_use(port: int) -> bool:
    with socket.socket() as s:
        s.settimeout(1)
        return s.connect_ex(("127.0.0.1", port)) == 0


def preflight() -> list[str]:
    """What keeps the check from starting; empty when nothing does."""
    problems = []
    if subprocess.run(["git", "status", "--porcelain"], cwd=REPO, capture_output=True, text=True).stdout.strip():
        problems.append("the worktree has uncommitted changes")
    try:
        if others := services.other_containers():
            problems.append(f"{others} running container(s) outside the {services.PROJECT} project")
        if ours := project_containers():
            problems.append(f"{ours} container(s) of the {services.PROJECT} project exist, maybe another session's")
    except (OSError, RuntimeError, subprocess.TimeoutExpired) as error:
        problems.append(f"docker: {error}")
    if busy := [str(port) for port in PORTS if port_in_use(port)]:
        problems.append(f"port(s) in use: {', '.join(busy)}")
    if not SNAPSHOT.is_dir():
        problems.append(f"no snapshot at {SNAPSHOT.relative_to(REPO)}")
    return problems


def report(record: dict) -> None:
    def mib(value: int | None) -> str:
        return "-" if value is None else f"{value / MiB:,.0f} MiB"

    m, budgets = record["measured"], record["budgets"]
    for service, c in m["containers"].items():
        print(f"{service}: anon {mib(c['anon_bytes'])} (budget {mib(budgets[f'{service} anon'])}); memory.peak "
              f"{mib(c['peak_bytes'])} of {mib(c['limit_bytes'])}; {c['lives']} li{'fe' if c['lives'] == 1 else 'ves'}, "
              f"limit reached {c['limit_hits']} times, {c['oom_kills']} OOM kills")
    for step, peak in sorted(m["steps"].items()):
        print(f"step {step}: {peak / GiB:.2f} GiB (budget {budgets.get(f'step {step}', 0) / GiB:.2f} GiB)")
    for job, steps in sorted(m["jobs"].items()):
        print(f"  {job}: " + ", ".join(f"{step} {peak / GiB:.2f} GiB" for step, peak in steps.items()))
    for name, p in m["processes"].items():
        budget = budgets.get(f"process {name}")
        print(f"{name}: {mib(p['rss_bytes'])} over {p['processes']} process(es)"
              + (f" (budget {mib(budget)})" if budget else ""))
    h = m["host"]
    print(f"host: {h['idle']['available_bytes'] / GiB:.2f} GiB available idle, {h['available_min_bytes'] / GiB:.2f} "
          f"at the lowest; compressor +{mib(h['compressor_growth_bytes'])}, swap +{mib(h['swap_growth_bytes'])}; "
          f"VM process RSS {mib(h['vm_rss_bytes'])}")
    verdict = record["verdict"]
    for reason in verdict["invalid"]:
        print(f"does not count: {reason}")
    for miss in verdict["misses"]:
        print(f"miss: {miss}")
    print("passed" if verdict["passed"] else "counts, failed" if verdict["counts"] else "does not count")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--out", type=Path, help="a new folder for record.json, the samples and the pytest logs")
    parser.add_argument("--preflight", action="store_true", help="only check that the run can start")
    parser.add_argument("--keep", action="store_true", help="keep pytest's temporary folders with the runs' outputs")
    args = parser.parse_args(argv)
    if not args.preflight and args.out is None:
        parser.error("--out is required, unless --preflight")
    problems = preflight()
    print(f"available now: {psutil.virtual_memory().available / GiB:.2f} GiB; with the stack up and idle "
          f"the run needs {HOST['idle_available'] / GiB:.1f} GiB")
    for problem in problems:
        print(f"not ready: {problem}")
    if args.preflight or problems:
        return 2 if problems else 0
    args.out.mkdir(parents=True)   # a new folder, so no record is overwritten
    temp = Path(tempfile.mkdtemp(prefix="etf-risk-memory-"))
    record: dict = {"format": 1, "started_at_utc": now(), "code": code_state(), "machine": machine(),
                    "budgets": BUDGETS, "host_limits": HOST, "settle_s": SETTLE_S, "pytest_temp": str(temp)}
    try:
        subprocess.Popen(["caffeinate", "-i", "-w", str(os.getpid())])   # no idle sleep while this runs
    except OSError:
        pass
    env = {**os.environ, "ETF_RISK_MYSQL_URL": services.DEFAULT_MYSQL_URL,
           "ETF_RISK_KAFKA_BOOTSTRAP": services.DEFAULT_KAFKA_BOOTSTRAP}
    started = False
    try:
        compose("up", "-d", "--wait", *services.SERVICES)
        started = True
        subprocess.run([sys.executable, "-m", "etf_risk.services", "ready", *services.SERVICES], cwd=REPO, env=env,
                       check=True, timeout=300)
        time.sleep(SETTLE_S)
        record["idle"] = idle = host_memory()
        print(f"idle with the stack up: {idle['available_bytes'] / GiB:.2f} GiB available")
        if idle["available_bytes"] < HOST["idle_available"]:
            record["verdict"] = {"counts": False, "passed": False, "misses": [],
                                 "invalid": [f"{idle['available_bytes'] / GiB:.2f} GiB available with the stack idle"]}
            print(f"not ready: below {HOST['idle_available'] / GiB:.1f} GiB")
            return 2
        sampler, runs = Sampler(args.out / "samples.jsonl"), {}
        sampler.start()
        try:
            runs["suites"] = run_pytest("suites", JOB_SUITES, env, args.out, temp, 1800)
            print(f"job suites: {runs['suites']}")
            runs["acceptance"] = run_pytest("acceptance", ACCEPTANCE, {**env, "ETF_RISK_LIVE_PIPELINE": "1"},
                                            args.out, temp, 3600)
            print(f"acceptance cases: {runs['acceptance']}")
        finally:
            sampler.stop()
        record["measured"] = measure(sampler, idle, temp, runs)
        record["verdict"] = judge(record["measured"])
    finally:
        if started:
            compose("down", "-v")
        record["ended_at_utc"] = now()
        record["project_containers_after"] = project_containers()
        keep_records(temp, args.out / "records")
        if not args.keep:
            shutil.rmtree(temp, ignore_errors=True)
        (args.out / "record.json").write_text(json.dumps(record, indent=2) + "\n")
    report(record)
    return 0 if record["verdict"]["passed"] else 1 if record["verdict"]["counts"] else 2


if __name__ == "__main__":
    sys.exit(main())

